<script setup lang="ts">
import { Plus } from "lucide-vue-next";
import { locationApi, type LocationApiItem, type LocationBusinessEntity, type LocationOrganizationContractor } from "~/api/location";
import { useLocationStore } from "~/stores/location";
import { useLocationOperationalAreaStore } from "~/stores/locationOperationalArea";
import ContractorCreateModal from "./components/ContractorCreateModal.vue";
import LocationCompaniesTab from "./components/LocationCompaniesTab.vue";
import LocationContractorsTab from "./components/LocationContractorsTab.vue";
import LocationOperationalAreasTab from "./components/LocationOperationalAreasTab.vue";
import LocationDetailCard from "./components/LocationDetailCard.vue";
import LocationEditDrawer from "~/components/locations/LocationEditDrawer.vue";
import { type DangerClass, type Contractor } from "~/data/location-detail.mock";
definePageMeta({ layout: "default" });
const route=useRoute(); const locationId=computed(()=>Number(route.params.locationId??1)); const tenantId=computed(()=>String(route.params.tenantId??"")); const locationStore=useLocationStore(); const operationalAreaStore=useLocationOperationalAreaStore(); const {setScope}=useOrganizationScope(); const {$toast}=useNuxtApp(); const runtimeConfig=useRuntimeConfig(); const location=ref<LocationApiItem|null>(null); const locationLoading=ref(true); const locationError=ref("");
const assetUrl=(path:string|null|undefined)=>{if(!path)return"";if(/^https?:\/\//i.test(path))return path;return new URL(`/storage${path.startsWith("/")?path:`/${path}`}`,runtimeConfig.public.apiBaseUrl).toString()};
const locationView=computed(()=>({id:locationId.value,name:location.value?.name??"",city:location.value?.city?.name??"",district:location.value?.district?.name??"",address:location.value?.address??"",image:assetUrl(location.value?.image),status:location.value?.is_active===false?("passive" as const):("active" as const)}));
const loadLocation=async()=>{locationLoading.value=true;locationError.value="";try{location.value=await locationStore.getLocation(tenantId.value,locationId.value)}catch(error){locationError.value=error instanceof Error?error.message:"Lokasyon bilgileri alınamadı."}finally{locationLoading.value=false}};
const activeTab=ref<"companies"|"contractors"|"areas">("companies"); const locationTabs=[{label:"Firmalar",key:"companies"},{label:"Alt Yükleniciler",key:"contractors"},{label:"Operasyonel Alanlar",key:"areas"}];
const showContractorModal=ref(false); const editingContractor=ref<Contractor|null>(null); const contractorModalLoading=ref(false); const contractorSaving=ref(false); const contractorUpdatingId=ref<number|null>(null); const contractors=ref<Contractor[]>([]); const contractorPool=ref<LocationOrganizationContractor[]>([]); const attachedBusinessEntities=ref<LocationBusinessEntity[]>([]); const contractorAreas=computed(()=>operationalAreaStore.areas); const operationalAreasTab=ref<InstanceType<typeof LocationOperationalAreasTab>|null>(null); const companiesTab=ref<InstanceType<typeof LocationCompaniesTab>|null>(null); const editDrawerOpen=ref(false); const editSaving=ref(false);
const saveLocation=async(payload:{name:string;city_id:number|null;district_id:number|null;address:string;status:"active"|"passive";file:File|null})=>{editSaving.value=true;try{const form=new FormData();form.append("name",payload.name);if(payload.city_id!==null)form.append("city_id",String(payload.city_id));if(payload.district_id!==null)form.append("district_id",String(payload.district_id));form.append("address",payload.address);form.append("is_active",payload.status==="active"?"1":"0");if(payload.file instanceof File)form.append("image",payload.file);location.value=await locationStore.updateLocation(tenantId.value,locationId.value,form);editDrawerOpen.value=false;$toast.success("Lokasyon bilgileri kaydedildi.")}catch(error){$toast.error(error instanceof Error?error.message:"Lokasyon güncellenemedi.")}finally{editSaving.value=false}};
const loadContractorData=async()=>{try{const[pool,attached]=await Promise.all([locationApi.organizationContractors(locationId.value),locationApi.businessEntities(locationId.value),operationalAreaStore.fetchAreas(locationId.value)]); contractorPool.value=pool.filter(x=>x.contractor_type==="permanent"); attachedBusinessEntities.value=attached.filter(x=>x.type==="contractor"); contractors.value=attachedBusinessEntities.value.map(entity=>{const poolItem=contractorPool.value.find(x=>x.business_entity_id===entity.id);const pivot=entity.pivot??{};return{id:pivot.id??entity.id,name:entity.name,logo:assetUrl(poolItem?.logo_path),operationalArea:contractorAreas.value.find(x=>x.id===pivot.operational_region_id)?.name||"Tüm Tesis",activity:pivot.activity||"",subActivity:pivot.sub_activity||"",nace:pivot.nace_code||"",dangerClass:(pivot.hazard_class||"") as DangerClass,sgk:pivot.sgk_workplace_number||"",status:poolItem?.status==="passive"?"passive":"active",contractorType:"Daimi",businessEntityId:entity.id}})}catch(error){locationError.value=error instanceof Error?error.message:"Alt yükleniciler alınamadı."}};
const availableContractors=computed(()=>{const attachedIds=new Set(attachedBusinessEntities.value.map(x=>x.id));return contractorPool.value.filter(x=>!attachedIds.has(x.business_entity_id)).map(x=>({businessEntityId:x.business_entity_id,name:x.name,logo:assetUrl(x.logo_path)}))});
const openAddContractor=()=>{editingContractor.value=null;showContractorModal.value=true};
const openEditContractor=async(contractor:Contractor)=>{editingContractor.value={...contractor};contractorModalLoading.value=true;showContractorModal.value=true;await nextTick();contractorModalLoading.value=false};
const closeContractorModal=()=>{if(contractorSaving.value)return;showContractorModal.value=false;editingContractor.value=null};
const saveContractor=async(p:{businessEntityId:number;areaId:number|null;activity:string;subActivity:string;nace:string;dangerClass:string;sgk:string})=>{if(contractorSaving.value||contractorUpdatingId.value!==null)return;const payload={operational_region_id:p.areaId,activity:p.activity,sub_activity:p.subActivity,nace_code:p.nace,hazard_class:p.dangerClass,sgk_workplace_number:p.sgk};if(editingContractor.value){const pivotId=editingContractor.value.id;showContractorModal.value=false;editingContractor.value=null;contractorUpdatingId.value=pivotId;try{await locationApi.updateBusinessEntity(locationId.value,pivotId,payload);$toast.success("Alt yüklenici bilgileri güncellendi.");await loadContractorData()}catch(error){$toast.error(error instanceof Error?error.message:"Alt yüklenici bilgileri kaydedilemedi.")}finally{contractorUpdatingId.value=null}}else{contractorSaving.value=true;try{await locationApi.createBusinessEntity(locationId.value,{business_entity_id:p.businessEntityId,...payload});$toast.success("Alt yüklenici lokasyona başarıyla bağlandı.");await loadContractorData();showContractorModal.value=false;editingContractor.value=null}catch(error){$toast.error(error instanceof Error?error.message:"Alt yüklenici bilgileri kaydedilemedi.")}finally{contractorSaving.value=false}}};
const removeContractor=async(pivotId:number)=>{try{await locationApi.removeBusinessEntity(locationId.value,pivotId);await loadContractorData();$toast.success("Alt yüklenici lokasyondan çıkarıldı")}catch(error){$toast.error(error instanceof Error?error.message:"Alt yüklenici lokasyondan çıkarılamadı")}};
onMounted(async()=>{await loadLocation();if(location.value){setScope("location",{id:location.value.id,name:location.value.name,description:"Tesis",icon:undefined});await loadContractorData()}});
</script>
<template><div class="font-outfit mx-auto w-full max-w-[1400px] location-detail-refinement"><LocationDetailCard :location="locationView" @edit="editDrawerOpen=true"/><LocationEditDrawer v-model="editDrawerOpen" :location="location" :loading="editSaving" @save="saveLocation"/><div v-if="locationError" class="mt-3 rounded-lg border border-error-200 bg-error-50 px-4 py-3 text-sm text-error-600">{{locationError}}</div><OrganizationTabs v-model="activeTab" :tabs="locationTabs"/><div class="mb-4 flex items-center justify-end"><button v-if="activeTab==='companies'" class="inline-flex h-10 items-center gap-2 rounded-lg bg-brand-500 px-4 text-sm font-semibold text-white" @click="companiesTab?.openCreate()"><Plus :size="16"/> Firma Ekle</button><button v-else-if="activeTab==='contractors'" class="inline-flex h-10 items-center gap-2 rounded-lg bg-brand-500 px-4 py-2 text-sm font-semibold text-white" @click="openAddContractor"><Plus :size="16"/> Alt Yüklenici Ekle</button><button v-else class="inline-flex h-10 items-center gap-2 rounded-lg bg-brand-500 px-4 text-sm font-semibold text-white" @click="operationalAreasTab?.openCreate()"><Plus :size="16"/> Operasyonel Alan Ekle</button></div><LocationCompaniesTab v-show="activeTab==='companies'" ref="companiesTab"/><LocationContractorsTab v-show="activeTab==='contractors'" :contractors="contractors" :updating-id="contractorUpdatingId" @remove="removeContractor" @edit="openEditContractor"/><LocationOperationalAreasTab v-show="activeTab==='areas'" ref="operationalAreasTab" :location-id="locationId"/><ContractorCreateModal v-model="showContractorModal" :contractors="availableContractors" :areas="contractorAreas" :edit-value="editingContractor" :loading="contractorModalLoading" :saving="contractorSaving" @save="saveContractor" @update:model-value="value=>{if(!value)closeContractorModal()}"/></div></template>
